Here is a basic implementation of a pendulum simulation using HTML5 canvas, JavaScript, and the laws of physics:

```html
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <title>Pendulum Simulation</title>
  <style>
    canvas {
      border: 1px solid black;
    }
  </style>
</head>
<body>
  <h1>Pendulum Simulation</h1>
  <input type="number" id="initialAngle" value="45" />
  <button id="start">Release</button>
  <canvas id="pendulum" width="400" height="400"></canvas>
  <script>
    let canvas = document.getElementById('pendulum');
    let ctx = canvas.getContext('2d');
    let initialAngle = 0;
    let angle = 0;
    let velocity = 0;
    let gravity = 0.981;
    let length = 150;
    let released = false;

    function init() {
      canvas.addEventListener('click', () => {
        initialAngle = parseInt(document.getElementById('initialAngle').value);
        angle = initialAngle * Math.PI / 180;
        velocity = 0;
        released = false;
      });

      document.getElementById('start').addEventListener('click', () => {
        if (!released) {
          released = true;
        }
      });

      animate();
    }

    function animate() {
      if (released) {
        velocity += gravity / length * Math.sin(angle);
        angle += velocity;
        if (Math.abs(angle) > Math.PI / 2) {
          released = false;
        }
      }

      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.translate(canvas.width / 2, canvas.height / 2);
      ctx.rotate(angle);
      ctx.beginPath();
      ctx.arc(0, length, 10, 0, 2 * Math.PI);
      ctx.fillStyle = 'blue';
      ctx.fill();
      ctx.closePath();

      requestAnimationFrame(animate);
    }

    init();
  </script>
</body>
</html>
```

